<?php require __DIR__.'/../layouts/header.php'; ?><h1>Category Management</h1><form method="post" action="index.php?action=category_save" class="form"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Name<input name="name" required value="<?=e($edit['name']??'')?>"></label><small class="error"><?=e($errors['name']??'')?></small><label>Type<select name="category_type" required><option value="">Choose</option><option value="liquid" <?=($edit['category_type']??'')==='liquid'?'selected':''?>>Liquid</option><option value="solid" <?=($edit['category_type']??'')==='solid'?'selected':''?>>Solid</option></select></label><small class="error"><?=e($errors['category_type']??'')?></small><button>Save</button></form><table><tr><th>ID</th><th>Name</th><th>Type</th><th>Actions</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['id']?></td><td><?=e($r['name'])?></td><td><?=e($r['category_type'])?></td><td><a href="index.php?action=category_edit&id=<?=$r['id']?>">Edit</a> <form class="inline" method="post" action="index.php?action=category_delete" data-confirm="Delete category?"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></table><?php require __DIR__.'/../layouts/footer.php'; ?>
